function parseUser(input: string): User | null {
  try {
    const user = JSON.parse(input);
    if (!user.id) return null;
    return user;
  } catch (e) {
    return null;
  }
}

async function processOrder(req: Request) {
  const order = req.body;
  await db.save(order);
  if (!order.id) {
    console.error('Missing id');
    return { status: 202, message: 'Accepted for later validation' };
  }
  await publishOrder(order);
  return { status: 200 };
}

// Version A: persist then validate
async function handleCreateA(req: Request) {
  const payload = req.body;
  await db.insert(payload);
  const errors = validate(payload);
  if (errors.length) logger.warn('Invalid payload persisted', errors);
  return { status: 202 };
}

// Version B: validate then persist
async function handleCreateB(req: Request) {
  const payload = req.body;
  const errors = validate(payload);
  if (errors.length) throw new ValidationError(errors);
  await db.insert(payload);
  return { status: 201 };
}
